import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.166.1/build/three.module.js';

const $ = (s) => document.querySelector(s);
const $$ = (s) => [...document.querySelectorAll(s)];
const STAGES = ['Local Cricket','District Cricket','State Cricket','Domestic Cricket','T20 League','International','World Cup'];
const stageNames = ['LOCAL CRICKET','DISTRICT CRICKET','STATE CRICKET','DOMESTIC CRICKET','T20 LEAGUE','INTERNATIONAL','WORLD CUP'];
const stageDetails = ['Start here','Earn your stripes','State selection','First-class cricket','The big league','Wear the crest','Lift the trophy'];
const freshCareer = () => ({name:'Arjun Singh',number:7,skin:'#ad7656',hair:'Short crop',style:'Right-hand bat',stage:0,rating:62,runs:0,balls:0,outs:0,fours:0,sixes:0,fifties:0,hundreds:0,wickets:0,catches:0,best:0,bestBowl:'—',matches:0,history:[],settings:{sound:true,vibration:true}});
let career;
try { career = {...freshCareer(), ...JSON.parse(localStorage.getItem('rc3-career') || '{}')}; } catch { career = freshCareer(); }
const save = () => localStorage.setItem('rc3-career', JSON.stringify(career));
let match = null;
let selectedRole = 'BAT';
let tossWon = false;
let tossCall = null;
let pendingField = null;
let toastTimer;
const showToast = (message) => {const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)};
function updateCareerUI(){
  $('#topName').textContent=career.name.toUpperCase();$('#previewName').textContent=career.name.toUpperCase();$('#previewNumber').textContent=String(career.number).padStart(2,'0');$('#heroStage').textContent=stageNames[career.stage];$('#heroRating').textContent=career.rating;$('#stageProgressLabel').textContent=`${career.stage+1} / 7`;$('#stageProgress').style.width=`${((career.stage+1)/7)*100}%`;
  $('#careerRuns').textContent=career.runs.toLocaleString();$('#careerAverage').textContent=career.outs?((career.runs/career.outs).toFixed(1)):'—';$('#worldRank').textContent=career.matches?`#${Math.max(1,Math.round(6000-career.rating*75-career.runs/2)).toLocaleString()}`:'#—';$('#rankDelta').textContent=career.matches?'RISING THROUGH THE RANKS':'PLAY TO GET RANKED';$('#nextFixture').textContent=stageNames[Math.min(6,career.stage+1)]+' TRIALS';
  $('#recordsRuns').textContent=career.runs.toLocaleString();$('#recordAverage').textContent=career.outs?(career.runs/career.outs).toFixed(2):'—';$('#recordSR').textContent=career.balls?(career.runs/career.balls*100).toFixed(1):'—';$('#recordMilestones').textContent=`${career.fifties} / ${career.hundreds}`;$('#recordBoundaries').textContent=`${career.fours} / ${career.sixes}`;$('#recordWickets').textContent=career.wickets;$('#recordBowling').textContent=career.bestBowl;$('#bestInnings').textContent=career.best||'—';$('#matchesPlayed').textContent=`${career.matches} MATCH${career.matches===1?'':'ES'} PLAYED`;
  $('#pathway').innerHTML=STAGES.map((s,i)=>`<div class="stage-item ${i===career.stage?'current':''} ${i<career.stage?'done':''}"><div class="stage-top"><b>${String(i+1).padStart(2,'0')}</b><span>${i<career.stage?'✓':i===career.stage?'●':'◌'}</span></div><strong>${stageNames[i]}</strong><small>${stageDetails[i]}</small></div>`).join('');
  $('#matchHistory').innerHTML=career.history.length?career.history.slice(0,5).map(m=>`<div class="history-row"><span>${m.opponent}</span><b>${m.runs} <small>(${m.balls})</small></b><span>${m.result}</span><span class="${m.win?'win':''}">${m.score}</span></div>`).join(''):'<div class="empty-history">Play your first match to start your record book.</div>';
}
function showView(name){$$('.view').forEach(v=>v.classList.remove('active-view'));$(`#${name}View`).classList.add('active-view');$$('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('#topTitle').textContent=({career:'OVERVIEW',match:'MATCH DAY',player:'MY PLAYER',records:'STATISTICS'})[name];if(name==='match')resizeScene();}
$$('.nav-link').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
$$('[data-view="records"]').forEach(b=>b.addEventListener('click',()=>showView('records')));
$('#continueBtn').onclick=$('#fixtureBtn').onclick=()=>{showView('match');resetPreMatch()};
$('#profileShortcut').onclick=()=>showView('player');
$('#settingsBtn').onclick=()=>openSettings();
function formatConfig(){const f=$('#formatSelect').value;return {T20:{overs:20,label:'T20 · 20 OVERS'},ODI:{overs:50,label:'ODI · 50 OVERS'},TEST:{overs:90,label:'TEST · 90 OVERS'},QUICK:{overs:2,label:'QUICK · 2 OVERS'}}[f]}
function resetPreMatch(){match=null;tossWon=false;tossCall=null;pendingField=null;$('#preMatchControls').classList.remove('hidden');$('#liveControls').classList.add('hidden');$('#sceneStatus').textContent='PRE-MATCH';$('#inningsMessage').textContent='Ready for the toss?';$('#liveScore').innerHTML='0<span>/0</span>';$('#oversLabel').textContent='0.0 OVERS';$('#scoreTeam').textContent='NORTHSIDE XI';$('#targetChip').textContent=formatConfig().label;$('#tossResult').textContent='Call the toss to begin';$('#startMatchBtn').disabled=true;$('#headsBtn').classList.remove('selected');$('#tailsBtn').classList.remove('selected');$('#liveDotText').textContent='● LIVE';scene.setMode('idle');}
$('#formatSelect').onchange=()=>{$('#targetChip').textContent=formatConfig().label};
$$('.role-choice').forEach(b=>b.onclick=()=>{$$('.role-choice').forEach(x=>x.classList.remove('active'));b.classList.add('active');selectedRole=b.dataset.role});
function toss(call){if(tossWon){showToast('Toss already called — start the match!');return}tossCall=call;const won=Math.random()<.5;tossWon=true;$('#headsBtn').classList.toggle('selected',call==='HEADS');$('#tailsBtn').classList.toggle('selected',call==='TAILS');const choice=selectedRole==='BAT'?'bat first':'field first';$('#tossResult').textContent=won?`You won the toss! You chose to ${choice}.`:`Riverdale won and elected to ${Math.random()<.5?'bat':'field'}.`;$('#startMatchBtn').disabled=false;showToast(won?'Toss won! Make it count.':'Toss lost — the match is on.');}
$('#headsBtn').onclick=()=>toss('HEADS');$('#tailsBtn').onclick=()=>toss('TAILS');
$('#startMatchBtn').onclick=()=>startMatch();$('#newMatchBtn').onclick=()=>resetPreMatch();
function startMatch(){const cfg=formatConfig();const userBats=(tossWon&&Math.random()<.5)?selectedRole==='BAT':selectedRole==='BAT';match={format:$('#formatSelect').value,oversMax:cfg.overs,innings:1,target:null,userBats,score:0,wickets:0,legal:0,balls:0,playerRuns:0,playerBalls:0,playerOut:false,nonRuns:0,nonBalls:0,outs:0,fours:0,sixes:0,partnership:0,partnershipBalls:0,bowlRuns:0,bowlWickets:0,bowlLegal:0,opponentScore:0,opponentWickets:0,opponentLegal:0,inningsRuns:[0,0],matchDone:false,careerMatch:true,overLog:[],shotNum:0};$('#sceneStatus').textContent='LIVE MATCH';$('#sceneStatus').style.color='var(--lime)';$('#preMatchControls').classList.add('hidden');$('#liveControls').classList.remove('hidden');$('#inningsNum').textContent='01';$('#targetChip').textContent=cfg.label;$('#scoreTeam').textContent=match.userBats?'NORTHSIDE XI':'RIVERDALE CC';$('#pitchLabel').textContent='NORTHSIDE CRICKET GROUND';$('#matchTitle').textContent=`${match.format==='TEST'?'TEST MATCH':match.format==='ODI'?'ONE DAY INTERNATIONAL':'T20 SELECTION MATCH'}`;$('#matchSub').textContent='Northside XI vs Riverdale CC · Northside Cricket Ground';$('#inningsMessage').textContent=match.userBats?'You’re in. Make this innings count.':'Take your mark. Set the field.';$('#actionLabel').textContent=match.userBats?'YOUR MOVE · BATTING':'YOUR MOVE · BOWLING';$('#actionPrompt').textContent=match.userBats?'Read the ball. Pick your shot.':'Set your line and length.';$('#actionHint').textContent=match.userBats?'Swipe in the arena or choose a shot below.':'Use the controls to shape your delivery.';$('#shotControls').classList.toggle('hidden',!match.userBats);$('#deliveryControls').classList.toggle('hidden',match.userBats);$('#fieldControls').classList.add('hidden');$('#resultLine').classList.add('hidden');$('#liveDotText').textContent='● LIVE';scene.setMode(match.userBats?'batting':'bowling');updateMatchUI();match.userBats?prepareBatterBall():setBowlingReady();}
function setBowlingReady(){if(!match||match.matchDone)return;$('#actionLabel').textContent='YOUR MOVE · BOWLING';$('#actionPrompt').textContent='Set your line and length.';$('#actionHint').textContent='A good plan beats a big hit. Vary your pace.';$('#deliveryControls').classList.remove('hidden');$('#fieldControls').classList.add('hidden');$('#resultLine').classList.add('hidden');scene.setMode('bowling');}
function prepareBatterBall(){if(!match||match.matchDone)return;if(match.legal>=match.oversMax*6||match.wickets>=10){endInnings();return}$('#actionLabel').textContent=`YOUR MOVE · BATTING · ${['COVER','STRAIGHT','PULL','CUT','SWEEP'][Math.floor(Math.random()*5)]} LINE`;$('#actionPrompt').textContent='Read the ball. Pick your shot.';$('#actionHint').textContent='Swipe in the arena or choose a shot below.';$('#shotControls').classList.remove('hidden');$('#deliveryControls').classList.add('hidden');$('#fieldControls').classList.add('hidden');$('#resultLine').classList.add('hidden');scene.setMode('batting');scene.deliver();}
$$('.shot-btn').forEach(b=>b.addEventListener('click',()=>playShot(b.dataset.shot)));
let swipeStart=null;$('#stadiumCanvas').addEventListener('pointerdown',e=>{swipeStart={x:e.clientX,y:e.clientY,time:performance.now()}});$('#stadiumCanvas').addEventListener('pointerup',e=>{if(!swipeStart||!match||!match.userBats||match.matchDone||!$('#resultLine').classList.contains('hidden'))return;const dx=e.clientX-swipeStart.x,dy=e.clientY-swipeStart.y;let shot='straight';if(Math.abs(dx)+Math.abs(dy)>18){if(dy<-25)shot=dx>30?'cover':'straight';else if(dx>28)shot='cut';else if(dx<-28)shot='sweep';else if(dy>25)shot='pull'}playShot(shot);swipeStart=null});
function playShot(shot){if(!match||!match.userBats||match.matchDone||!$('#resultLine').classList.contains('hidden'))return;$('#shotControls').classList.add('hidden');const r=resolvePlayerShot(shot);renderOutcome(r);}
function resolvePlayerShot(shot){const skill=(career.rating-50)/100;const timing=Math.random();let quality=.47+skill*.28+(Math.random()-.5)*.37;const bonus={cover:.06,straight:.04,pull:.015,cut:.01,sweep:-.03,defend:.12,leave:0}[shot]||0;quality=Math.max(.02,Math.min(.99,quality+bonus));const delivery=scene.deliveryProfile;let runs=0,wicket=false,kind='';const isDef=shot==='defend';if(shot==='leave'){if(Math.random()<.07){wicket=true;kind='bowled'}else kind='dot'}else if(isDef){if(quality<.16){wicket=Math.random()<.25;kind=wicket?'edge':'dot'}else kind=Math.random()<.25?'single':'dot'}else if(quality<.13){wicket=true;kind=Math.random()<.65?'caught':'bowled'}else if(quality<.24){kind='edge';runs=Math.random()<.32?4:Math.random()<.4?1:0;if(runs===4)kind='four'}else if(quality<.39){runs=Math.random()<.55?1:Math.random()<.75?2:0;kind=runs?'runs':'dot'}else if(quality<.64){runs=Math.random()<.25?1:Math.random()<.76?2:3;kind='runs'}else if(quality<.79){runs=Math.random()<.42?4:Math.random()<.72?2:1;kind=runs===4?'four':'runs'}else {runs=Math.random()<.70?4:6;kind=runs===4?'four':'six'}if(delivery&&delivery.line>75&&shot==='cover'){quality*=.72}if(timing<.10&&runs>0){runs=Math.max(0,runs-1);if(runs===0)kind='dot'}if(timing>.91&&runs>=4&&Math.random()<.35){wicket=true;kind='caught';runs=0}return{runs,wicket,kind,shot,quality,timing,detail:wicket?'A faint edge. The keeper takes it.':kind==='four'?'Timed sweetly into the gap.':kind==='six'?'Clean strike — that’s gone all the way!':kind==='edge'?'A thick edge squirts away.':runs?`Good running. ${runs===1?'Quick single.':runs===2?'They come back for two.':'Excellent placement.'}`:'The bowler wins that one.'}}
function renderOutcome(r){match.shotNum++;match.playerBalls++;match.balls++;if(r.wicket){match.wickets++;match.outs++;match.playerOut=true;match.bowlWickets++;career.outs++;r.runs=0}else{match.score+=r.runs;match.playerRuns+=r.runs;match.partnership+=r.runs;match.partnershipBalls++;match.bowlRuns+=r.runs;if(r.runs===4)match.fours++;if(r.runs===6)match.sixes++;if(r.runs===4)career.fours++;if(r.runs===6)career.sixes++;if(r.runs===1||r.runs===3)swapStrike()}match.legal++;match.bowlLegal++;match.inningsRuns[0]=match.score;match.overLog.push(r.wicket?'W':r.runs===0?'·':String(r.runs));scene.hit(r);showResult(r);updateMatchUI();}
function swapStrike(){[match.playerRuns,match.nonRuns]=[match.nonRuns,match.playerRuns];[match.playerBalls,match.nonBalls]=[match.nonBalls,match.playerBalls];showToast('Single taken — you’re at the striker’s end!')}
function showResult(r){$('#shotControls').classList.add('hidden');$('#deliveryControls').classList.add('hidden');$('#fieldControls').classList.add('hidden');$('#resultLine').classList.remove('hidden');$('#resultText').textContent=r.wicket?'OUT!':r.runs===6?'SIX!':r.runs===4?'FOUR!':r.runs===0?'DOT BALL':`${r.runs} RUN${r.runs===1?'':'S'}`;$('#resultIcon').textContent=r.wicket?'✕':r.runs>=4?'✦':'◈';$('#resultDetail').textContent=r.detail;$('#nextBallBtn').textContent=(match.legal>=match.oversMax*6||match.wickets>=10)?'INNINGS BREAK →':'NEXT BALL →';$('#nextBallBtn').onclick=()=>{if(match.legal>=match.oversMax*6||match.wickets>=10)endInnings();else{if(match.legal%6===0&&match.legal>0)swapStrike();match.playerOut=false;prepareBatterBall()}};}
$('#paceSlider').oninput=e=>{$('#paceValue').textContent=e.target.value>75?'EXPRESS':e.target.value>55?'MEDIUM':e.target.value>30?'PACE':'SLOW'};$('#lineSlider').oninput=e=>{$('#lineValue').textContent=e.target.value<25?'LEG STUMP':e.target.value<45?'OFF STUMP':e.target.value<65?'OUTSIDE OFF':'WIDE OUTSIDE'};$('#lengthSlider').oninput=e=>{$('#lengthValue').textContent=e.target.value<25?'YORKER':e.target.value<42?'FULL':e.target.value<65?'GOOD':'SHORT'};
$('#deliverBtn').onclick=deliverBall;
function deliverBall(){if(!match||match.userBats||match.matchDone||!$('#resultLine').classList.contains('hidden'))return;const pace=+$('#paceSlider').value,line=+$('#lineSlider').value,length=+$('#lengthSlider').value;scene.deliveryProfile={pace,line,length};scene.deliver();$('#deliveryControls').classList.add('hidden');const risk=(pace/100)*.3+(length>72?.18:0)+(length<18?.1:0)+(line>75?.12:0);let r={runs:0,wicket:false,kind:'dot',detail:''};const chance=Math.random();if(chance<.045+risk*.05){r.wicket=true;r.kind='bowled';r.detail='Bowled him! The stumps are shattered.'}else if(chance<.12+risk*.12){r.runs=0;r.kind='dot';r.detail='Beaten for pace. A lovely delivery.'}else if(chance<.20+risk*.15){r.runs=Math.random()<.7?1:2;r.kind='runs';r.detail='Worked into the leg side. The batters run.'}else if(chance<.29+risk*.18){r.wicket=true;r.kind='caught';r.detail='High in the air! A chance in the deep.'}else if(chance<.42+risk*.18){r.runs=4;r.kind='four';r.detail='Punished! The batter finds the boundary.'}else if(chance<.46+risk*.12){r.runs=6;r.kind='six';r.detail='Launched into the stands. Six runs.'}else{r.runs=0;r.kind='dot';r.detail='Defended safely back to the bowler.'}if(r.wicket&&r.kind==='caught'&&Math.random()<.74){pendingField=r;$('#fieldControls').classList.remove('hidden');$('#fieldPrompt').innerHTML='<span>◉</span><b>CAUGHT IN THE AIR!</b> &nbsp; Move under it and take the catch.';$('#catchBtn').textContent='DIVE / CATCH ↗';$('#throwBtn').classList.add('hidden');scene.setMode('fielding');scene.catchChance();return}if(!r.wicket&&r.runs>0){match.opponentScore+=r.runs;match.score+=r.runs;match.bowlRuns+=r.runs;if(r.runs===1)swapStrike()}if(r.wicket){match.wickets++;match.opponentWickets++;match.bowlWickets++}match.legal++;match.bowlLegal++;match.balls++;match.overLog.push(r.wicket?'W':r.runs===0?'·':String(r.runs));scene.hit(r);showResult(r);updateMatchUI()}
$('#catchBtn').onclick=()=>{if(!pendingField)return;const caught=Math.random()<(.48+career.rating/250);const r=pendingField;pendingField=null;$('#fieldControls').classList.add('hidden');if(caught){r.wicket=true;r.runs=0;r.kind='caught';r.detail='Brilliant catch! You timed your dive perfectly.';match.wickets++;match.opponentWickets++;match.bowlWickets++;match.catches++;career.catches=(career.catches||0)+1;match.legal++;match.bowlLegal++;match.balls++;match.overLog.push('W')}else{r.wicket=false;r.runs=Math.random()<.55?1:0;r.kind=r.runs?'runs':'dot';r.detail='It spills! The fielder cannot hold on.';match.score+=r.runs;match.opponentScore+=r.runs;if(r.runs===1)swapStrike();match.legal++;match.bowlLegal++;match.balls++;match.overLog.push(String(r.runs))}scene.hit(r);showResult(r);updateMatchUI()};
$('#throwBtn').onclick=()=>{showToast('Throw released — the batters are safely home.');$('#throwBtn').classList.add('hidden')};
function updateMatchUI(){if(!match)return;const total=match.score,w=match.wickets,legal=match.legal;$('#liveScore').innerHTML=`${total}<span>/${w}</span>`;$('#oversLabel').textContent=`${Math.floor(legal/6)}.${legal%6} OVERS`;$('#strikerName').innerHTML=`${career.name} <i>★</i>`;$('#strikerRuns').textContent=match.playerRuns;$('#strikerBalls').textContent=match.playerBalls;$('#strikerSR').textContent=match.playerBalls?(match.playerRuns/match.playerBalls*100).toFixed(1):'—';$('#nonStrikerRuns').textContent=match.nonRuns;$('#nonStrikerBalls').textContent=match.nonBalls;$('#inningsMessage').textContent=match.innings===2?`Target ${match.target} · ${Math.max(0,match.target-match.score)} to win`:match.userBats?'You’re in. Make this innings count.':'Build pressure. Find the breakthrough.';$('#runRate').textContent=legal?(total/(legal/6)).toFixed(2):'0.00';$('#requiredRate').textContent=match.target?Math.max(0,(match.target-total)/Math.max(1,(match.oversMax*6-legal))*6).toFixed(2):'—';$('#partnership').innerHTML=`${match.partnership} <small>(${match.partnershipBalls})</small>`;$('#boundaries').innerHTML=`${match.fours} <small>4s</small> &nbsp; ${match.sixes} <small>6s</small>`;$('#bowlerFigures').textContent=`${match.bowlWickets}–${match.bowlRuns} · ${Math.floor(match.bowlLegal/6)}.${match.bowlLegal%6}`;$('#overBalls').innerHTML=Array.from({length:6},(_,i)=>`<i class="${match.overLog.slice(-6)[i]===undefined?'empty':''}">${match.overLog.slice(-6)[i]||'·'}</i>`).join('');$('#targetChip').textContent=match.target?`TARGET ${match.target}`:formatConfig().label;}
function endInnings(){if(!match||match.matchDone)return;if(match.innings===1){match.inningsRuns[0]=match.score;match.target=match.score+1;match.innings=2;match.userBats=!match.userBats;match.score=0;match.wickets=0;match.legal=0;match.balls=0;match.playerRuns=0;match.playerBalls=0;match.playerOut=false;match.nonRuns=0;match.nonBalls=0;match.outs=0;match.fours=0;match.sixes=0;match.partnership=0;match.partnershipBalls=0;match.bowlRuns=0;match.bowlWickets=0;match.bowlLegal=0;match.overLog=[];match.inningsRuns[1]=0;$('#inningsNum').textContent='02';$('#scoreTeam').textContent=match.userBats?'NORTHSIDE XI':'RIVERDALE CC';$('#inningsMessage').textContent=`Innings break · Target ${match.target}`;$('#resultLine').classList.add('hidden');showToast(`Innings break. Target: ${match.target}`);updateMatchUI();setTimeout(()=>{if(match.userBats){$('#shotControls').classList.remove('hidden');$('#deliveryControls').classList.add('hidden');prepareBatterBall()}else setBowlingReady()},650)}else finishMatch()}
function finishMatch(){match.matchDone=true;$('#liveDotText').textContent='● COMPLETE';$('#sceneStatus').textContent='MATCH COMPLETE';$('#actionPrompt').textContent='The final result is in.';$('#actionHint').textContent='Check your scorecard or start another match.';$('#shotControls').classList.add('hidden');$('#deliveryControls').classList.add('hidden');$('#fieldControls').classList.add('hidden');$('#resultLine').classList.add('hidden');const userTotal=match.userBats?match.inningsRuns[0]:match.inningsRuns[1];const opponentTotal=match.userBats?match.inningsRuns[1]:match.inningsRuns[0];const win=userTotal>opponentTotal;const result=userTotal===opponentTotal?'TIE':win?'WIN':'LOSS';const resultText=result==='TIE'?'Match tied':win?'You win! A brilliant performance.':'Riverdale win this time. Come back stronger.';career.runs+=match.playerRuns;career.balls+=match.playerBalls;career.best=Math.max(career.best,match.playerRuns);career.matches++;career.wickets+=match.bowlWickets;career.rating=Math.min(99,career.rating+Math.max(1,Math.floor(match.playerRuns/18)+(win?2:0)));if(match.playerRuns>=100)career.hundreds++;else if(match.playerRuns>=50)career.fifties++;const threshold=career.stage===0?15:career.stage<3?26:career.stage<5?35:45;if(career.stage<6&&(match.playerRuns>=threshold||win&&match.playerRuns>=8)){career.stage++;showToast(`Selected for ${stageNames[career.stage]}! Career stage unlocked.`)}career.history.unshift({opponent:'Riverdale CC',runs:match.playerRuns,balls:match.playerBalls,result,score:`${userTotal}/${match.wickets}`,win});career.history=career.history.slice(0,10);save();updateCareerUI();openResult(resultText,userTotal,opponentTotal,win);}
function openResult(message,userTotal,opponentTotal,win){openModal(`<div class="modal-head"><h2>${win?'VICTORY':userTotal===opponentTotal?'MATCH TIED':'MATCH COMPLETE'}</h2><button class="close-modal">×</button></div><p style="color:#aab8a8;font-size:10px">${message}</p><div class="modal-summary"><span>NORTHSIDE XI</span><strong>${userTotal}</strong><span>RIVERDALE CC</span><strong>${opponentTotal}</strong></div><table class="score-table"><thead><tr><th>YOUR INNINGS</th><th>RUNS</th><th>BALLS</th><th>SR</th></tr></thead><tbody><tr><td>${career.name}</td><td>${match.playerRuns}</td><td>${match.playerBalls}</td><td>${match.playerBalls?(match.playerRuns/match.playerBalls*100).toFixed(1):'—'}</td></tr><tr><td>Wickets / Catches</td><td>${match.bowlWickets}</td><td>${match.catches}</td><td>Rating +${career.rating-62}</td></tr></tbody></table><div class="modal-actions"><button class="outline-btn close-action">CLOSE</button><button class="primary-btn new-game-action">PLAY AGAIN ↗</button></div>`);$('.close-modal').onclick=closeModal;$('.close-action').onclick=closeModal;$('.new-game-action').onclick=()=>{closeModal();resetPreMatch()}}
function openModal(html){$('#modalContent').innerHTML=html;$('#modalBackdrop').classList.remove('hidden')}
function closeModal(){$('#modalBackdrop').classList.add('hidden')}
$('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});
